codeExamples.java:
public class Main {
    public static void main(String[] args) {
        int total = 0;
        for (int i = 1; i <= 5; i++) {
            total += i;
            System.out.println("Step " + i + ": running total = " + total);
        }
        System.out.println("Final Sum: " + total);
    }
}

