codeExamples.cpp:
#include <iostream>
int main() {
    int total = 0;
    for (int i = 1; i <= 5; i++) {
        total += i;
        std::cout << "Step " << i << ": running total = " << total << std::endl;
    }
    std::cout << "Final Sum: " << total << std::endl;
    return 0;
}
